.form-input:focus {
  outline: none;
  border-color: #2563eb;
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
}

.form-input.error {
  border-color: #dc2626;
}

.error-message {
  color: #dc2626;
  font-size: 0.8125rem;
  margin-top: 0.375rem;
}

/* Review details */
.review-card {
  background-color: #f9fafb;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  padding: 1.25rem;
  margin-bottom: 1.5rem;
